package redact

import (
	"regexp"
	"strings"
)

var sensitiveHeaders = map[string]struct{}{

	"authorization": {}, "cookie": {}, "set-cookie": {}, "proxy-authorization": {}, "x-api-key": {},
}

var bearerPattern = regexp.MustCompile(`(?i)bearer\s+[A-Za-z0-9._~+/=-]+`)
var assignmentPattern = regexp.MustCompile(`(?i)(password|passwd|token|api[_-]?key|secret)\s*[:=]\s*[^\s]+`)
var privateKeyPattern = regexp.MustCompile(`(?s)-----BEGIN [A-Z ]*PRIVATE KEY-----.*?-----END [A-Z ]*PRIVATE KEY-----`)

func Header(name, value string) string {

	if _, ok := sensitiveHeaders[strings.ToLower(strings.TrimSpace(name))]; ok {
		return "[REDACTED]"
	}
	return Text(value)
}

func Text(v string) string {
	v = privateKeyPattern.ReplaceAllString(v, "[PRIVATE KEY REDACTED]")

	v = bearerPattern.ReplaceAllString(v, "Bearer [REDACTED]")
	return assignmentPattern.ReplaceAllString(v, "$1=[REDACTED]")
}

package redact

import "testing"

func TestSensitiveHeadersAreRedacted(t *testing.T) {
	if got := Header("Authorization", "Bearer secret"); got != "[REDACTED]" {
		t.Fatalf("got %q", got)
	}

	if got := Header("Cookie", "session=abc"); got != "[REDACTED]" {
		t.Fatalf("got %q", got)
	}
}

func TestBearerTokensAreRedactedFromText(t *testing.T) {
	got := Text("request failed: Bearer abc.def-123")
	if got != "request failed: Bearer [REDACTED]" {

		t.Fatalf("got %q", got)
	}
}

package resilience

import (
	"errors"
	"sync"
	"time"
)

var ErrCircuitOpen = errors.New("circuit breaker open")

type CircuitState string

const (
	Closed   CircuitState = "closed"
	Open     CircuitState = "open"
	HalfOpen CircuitState = "half_open"

}

func (c *Circuit) Allow(now time.Time) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.State == "" {
		c.State = Closed
	}

if c.State == Open {
	if now.Sub(c.OpenedAt) >= c.Policy.OpenDuration {
		c.State = HalfOpen
		return nil
	}
	return ErrCircuitOpen
}
return nil

}
func (c *Circuit) Success() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.State = Closed
	c.Failures = 0
	c.OpenedAt = time.Time{}
}

func (c *Circuit) Failure(now time.Time) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.Failures++
	threshold := c.Policy.FailureThreshold
	if threshold < 1 {
		threshold = 5
	}

	if c.Failures >= threshold || c.State == HalfOpen {
		c.State = Open
		c.OpenedAt = now
	}
}

	FailureThreshold int
	OpenDuration     time.Duration
}

func DefaultPolicy() Policy {
	return Policy{BaseDelay: time.Second, MaxDelay: 30 * time.Second, MaxAttempts: 5, FailureThreshold: 5, OpenDuration: time.Minute}
}
func (p Policy) Delay(attempt int) time.Duration {

if attempt < 1 {
	attempt = 1
}
d := p.BaseDelay
if d <= 0 {
	d = time.Second
}
max := p.MaxDelay

if max <= 0 {
	max = 30 * time.Second
}
for i := 1; i < attempt && d < max; i++ {
	d *= 2
	if d > max {
		d = max
	}

	}
	return d
}

