	"time"
)

type Classifier func(error) ErrorClass

type Retrier struct {
	Policy   Policy
	Circuit  *Circuit
	Classify Classifier
}

func (r Retrier) Do(ctx context.Context, fn func() error) error {
	p := r.Policy

if p.MaxAttempts < 1 {
	p = DefaultPolicy()
}
for attempt := 1; attempt <= p.MaxAttempts; attempt++ {
	if r.Circuit != nil {
		if err := r.Circuit.Allow(time.Now()); err != nil {
			return err
		}

}
err := fn()
if err == nil {
	if r.Circuit != nil {
		r.Circuit.Success()
	}
	return nil
}

class := Unknown
if r.Classify != nil {
	class = r.Classify(err)
}
if class == Permanent {
	return err
}
if r.Circuit != nil {

	r.Circuit.Failure(time.Now())
}
if attempt == p.MaxAttempts {
	return err
}
delay := p.Delay(attempt)
select {
case <-ctx.Done():

			return ctx.Err()
		case <-time.After(delay):
		}
	}
	return nil
}

func TestRetryEventuallySucceeds(t *testing.T) {
	calls := 0
	r := Retrier{Policy: Policy{BaseDelay: time.Millisecond, MaxDelay: 2 * time.Millisecond, MaxAttempts: 4, FailureThreshold: 10}, Classify: func(error) ErrorClass { return Retryable }}
	err := r.Do(context.Background(), func() error {
		calls++
		if calls < 3 {
			return errors.New("temporary")

		}
		return nil
	})
	if err != nil || calls != 3 {
		t.Fatalf("err=%v calls=%d", err, calls)
	}
}
func TestPermanentDoesNotRetry(t *testing.T) {

	calls := 0
	r := Retrier{Policy: DefaultPolicy(), Classify: func(error) ErrorClass { return Permanent }}
	err := r.Do(context.Background(), func() error { calls++; return errors.New("bad") })
	if err == nil || calls != 1 {
		t.Fatalf("calls=%d", calls)
	}
}
func TestCircuitOpens(t *testing.T) {

	c := &Circuit{Policy: Policy{FailureThreshold: 2, OpenDuration: time.Minute}}
	now := time.Now()
	c.Failure(now)
	c.Failure(now)
	if err := c.Allow(now.Add(time.Second)); !errors.Is(err, ErrCircuitOpen) {
		t.Fatalf("expected open got %v", err)
	}
}

